import React from 'react'
import Image from 'next/image'

const Hero = () => {
  return (
    <section className="min-h-screen bg-amber-100">
        <Image
          src="/MitraAILogo.svg" 
          alt="MitraAI logo"
          width={40}
          height={40}
          className="w-10 h-10"
        />
    </section>
  )
}

export default Hero